<?php require 'config/database.php';auth(); $stats=[];$stats['customers']=$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn();$stats['repairs']=$pdo->query('SELECT COUNT(*) FROM repairs')->fetchColumn();$stats['products']=$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$today=$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(created_at)=CURDATE()")->fetchColumn();$salesToday=$pdo->query("SELECT COALESCE(SUM(paid),0) FROM sales WHERE DATE(created_at)=CURDATE()")->fetchColumn();$expenses=$pdo->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(created_at)=CURDATE()")->fetchColumn();$income=$today+$salesToday;$net=$income-$expenses;?>
